/**
 * GET /api/payments/disputes
 *
 * Lists stripe_disputes for the authenticated studio, joined with
 * their dispute_defense_packs row. Sorted by evidence_due_by ASC
 * (most urgent first), then created_at DESC.
 *
 * Access: owner | admin only. Artists and receptionists do not
 * interact with Stripe disputes.
 *
 * RLS on stripe_disputes scopes rows to the member's studio_id —
 * authed client only (no service-role needed for reads).
 *
 * Filter: ?status=needs_response|all  (default: all)
 */

import type { NextRequest } from 'next/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { getClientIp } from '@/lib/rate-limit/get-client-ip'
import { logger } from '@/lib/logger'
import type {
  StripeDisputeRow,
  DisputeDefensePackRow,
  StripeDisputeStatus,
} from '@/lib/payments/contracts'

// ─── Role gate ────────────────────────────────────────────────────────────────

const ALLOWED_ROLES = new Set(['owner', 'admin'])

// ─── Query types (stripe_disputes not in generated types) ─────────────────────

type DisputeWithPackRow = StripeDisputeRow & {
  dispute_defense_packs: Pick<
    DisputeDefensePackRow,
    | 'id'
    | 'signed_consent_url'
    | 'photo_release_url'
    | 'session_photos_urls'
    | 'chat_history_url'
    | 'deposit_policy_text'
    | 'receipt_url'
    | 'bundle_pdf_url'
    | 'generated_at'
  > | null
}

type UnknownQueryBuilder = {
  select: (cols: string, opts?: Record<string, unknown>) => UnknownQueryBuilder
  eq: (col: string, val: string) => UnknownQueryBuilder
  in: (col: string, vals: StripeDisputeStatus[]) => UnknownQueryBuilder
  order: (col: string, opts?: Record<string, unknown>) => UnknownQueryBuilder
  then: Promise<{
    data: DisputeWithPackRow[] | null
    error: { message: string } | null
  }>['then']
}

// ─── Handler ──────────────────────────────────────────────────────────────────

export async function GET(req: NextRequest): Promise<Response> {
  // 1. Rate limit
  const ip = getClientIp(req)
  const { success: rateLimitOk } = await authedRatelimit.limit(ip)
  if (!rateLimitOk) {
    return Response.json(
      { error: 'rate_limited', message: 'Too many requests. Please try again shortly.' },
      { status: 429 },
    )
  }

  // 2. Auth
  const supabase = await createClient()
  const {
    data: { user },
    error: authErr,
  } = await supabase.auth.getUser()

  if (authErr || !user) {
    return Response.json({ error: 'unauthorized', message: 'Authentication required.' }, { status: 401 })
  }

  // 3. Role gate — owner | admin only
  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (!member) {
    return Response.json({ error: 'forbidden', message: 'No studio membership found.' }, { status: 403 })
  }

  if (!ALLOWED_ROLES.has(member.role)) {
    return Response.json(
      { error: 'forbidden', message: 'Only studio owners or admins can view disputes.' },
      { status: 403 },
    )
  }

  // 4. Parse filter param
  const url = req.nextUrl
  const statusFilter = url.searchParams.get('status') ?? 'all'

  const NEEDS_RESPONSE_STATUSES: StripeDisputeStatus[] = [
    'needs_response',
    'warning_needs_response',
  ]

  // 5. Query stripe_disputes joined with dispute_defense_packs
  //    Tables not in generated types — cast through unknown following CC28 pattern.
  const disputeQuery = supabase.from('stripe_disputes') as unknown as UnknownQueryBuilder

  let query = disputeQuery.select(
    `
      id,
      studio_id,
      dispute_id,
      charge_id,
      reason,
      status,
      amount_cents,
      currency,
      evidence_due_by,
      defense_pack_status,
      defense_pack_url,
      submitted_at,
      resolved_at,
      resolved_amount_cents,
      created_at,
      dispute_defense_packs (
        id,
        signed_consent_url,
        photo_release_url,
        session_photos_urls,
        chat_history_url,
        deposit_policy_text,
        receipt_url,
        bundle_pdf_url,
        generated_at
      )
    `,
    { count: 'exact' },
  ).eq('studio_id', member.studio_id)

  if (statusFilter === 'needs_response') {
    query = query.in('status', NEEDS_RESPONSE_STATUSES)
  }

  // Sort: evidence_due_by ASC nulls last, then created_at DESC
  query = query
    .order('evidence_due_by', { ascending: true, nullsFirst: false })
    .order('created_at', { ascending: false })

  const result = await (query as unknown as Promise<{
    data: DisputeWithPackRow[] | null
    error: { message: string } | null
  }>)

  if (result.error) {
    logger.error(
      { studioId: member.studio_id, err: result.error },
      'disputes list: query failed',
    )
    return Response.json(
      { error: 'internal_error', message: 'Failed to load disputes.' },
      { status: 500 },
    )
  }

  return Response.json({ data: result.data ?? [] })
}

/**
 * POST /api/payments/disputes/[disputeId]/submit
 *
 * Manually submits a ready defense pack to Stripe before the cron fires.
 * Mirrors the exact evidence shape used by dispute-evidence-submitter.ts.
 *
 * Access: owner | admin only (expensiveRatelimit — calls Stripe).
 *
 * Idempotency: returns 409 if defense_pack_status !== 'ready'.
 * Stripe-side: evidence_already_submitted is handled gracefully (treated as success).
 *
 * Flow:
 *   1. Rate limit (expensiveRatelimit, keyed by studio_id)
 *   2. Auth + role gate
 *   3. Verify dispute exists and belongs to this studio (authed client — RLS applies)
 *   4. Verify defense_pack_status === 'ready' (409 otherwise)
 *   5. Fetch dispute_defense_packs row
 *   6. Build Stripe evidence object — same mapping as cron
 *   7. stripe.disputes.update(stripeDisputeId, { evidence, submit: true })
 *   8. RPC: stripe_dispute_set_defense_pack_status (service-role)
 *   9. Audit log
 */

import type { NextRequest } from 'next/server'
import { createClient, createServiceRoleClient } from '@/lib/supabase/server'
import { expensiveRatelimit } from '@/lib/rate-limit'
import { logAuditAction } from '@/lib/audit'
import { logger } from '@/lib/logger'
import { getStripe } from '@/lib/stripe/client'
import { RPC } from '@/lib/payments/contracts'
import type {
  StripeDisputeRow,
  DisputeDefensePackRow,
  DisputeDefensePackStatus,
} from '@/lib/payments/contracts'

// ─── Constants ────────────────────────────────────────────────────────────────

/** Stripe evidence text field hard limit. */
const STRIPE_TEXT_MAX = 9000

const ALLOWED_ROLES = new Set(['owner', 'admin'])

// ─── Untyped query helper ────────────────────────────────────────────────────

type DisputeCheckRow = Pick<
  StripeDisputeRow,
  | 'id'
  | 'studio_id'
  | 'dispute_id'
  | 'charge_id'
  | 'defense_pack_status'
  | 'defense_pack_url'
  | 'status'
>

type RpcFn = (
  fn: string,
  args: Record<string, unknown>,
) => Promise<{ data: unknown; error: { message: string } | null }>

// ─── Stripe error type guard (mirrors cron pattern) ──────────────────────────

interface StripeErrorLike {
  type: string
  code?: string
  message?: string
  statusCode?: number
}

function isStripeError(err: unknown): err is StripeErrorLike {
  return (
    typeof err === 'object' &&
    err !== null &&
    'type' in err &&
    typeof (err as Record<string, unknown>).type === 'string'
  )
}

// ─── Handler ──────────────────────────────────────────────────────────────────

export async function POST(
  req: NextRequest,
  context: { params: Promise<{ disputeId: string }> },
): Promise<Response> {
  const { disputeId } = await context.params

  if (!disputeId || typeof disputeId !== 'string' || disputeId.trim() === '') {
    return Response.json({ error: 'invalid_request', message: 'disputeId is required.' }, { status: 400 })
  }

  // 1. Auth
  const supabase = await createClient()
  const {
    data: { user },
    error: authErr,
  } = await supabase.auth.getUser()

  if (authErr || !user) {
    return Response.json({ error: 'unauthorized', message: 'Authentication required.' }, { status: 401 })
  }

  // 2. Role gate + studio resolution
  const { data: member } = await supabase
    .from('studio_members')
    .select('studio_id, role')
    .eq('user_id', user.id)
    .is('deactivated_at', null)
    .order('created_at', { ascending: true })
    .limit(1)
    .single()

  if (!member) {
    return Response.json({ error: 'forbidden', message: 'No studio membership found.' }, { status: 403 })
  }

  if (!ALLOWED_ROLES.has(member.role)) {
    return Response.json(
      { error: 'forbidden', message: 'Only studio owners or admins can submit dispute evidence.' },
      { status: 403 },
    )
  }

  // 3. Rate limit (expensive — keyed to studio to prevent burst Stripe calls)
  const { success: rateLimitOk } = await expensiveRatelimit.limit(member.studio_id)
  if (!rateLimitOk) {
    return Response.json(
      { error: 'rate_limited', message: 'Too many requests. Please try again shortly.' },
      { status: 429 },
    )
  }

  // 4. Verify dispute exists and belongs to this studio (authed client — RLS scopes to studio)
  const disputeQuery = supabase.from('stripe_disputes') as unknown as {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        eq: (col: string, val: string) => {
          maybeSingle: () => Promise<{
            data: DisputeCheckRow | null
            error: { message: string } | null
          }>
        }
      }
    }
  }

  const { data: disputeRow, error: disputeErr } = await disputeQuery
    .select('id, studio_id, dispute_id, charge_id, defense_pack_status, defense_pack_url, status')
    .eq('dispute_id', disputeId)
    .eq('studio_id', member.studio_id)
    .maybeSingle()

  if (disputeErr) {
    logger.error({ disputeId, studioId: member.studio_id, err: disputeErr }, 'disputes/submit: lookup error')
    return Response.json({ error: 'internal_error', message: 'Failed to look up dispute.' }, { status: 500 })
  }

  if (!disputeRow) {
    return Response.json(
      { error: 'not_found', message: 'Dispute not found or not accessible.' },
      { status: 404 },
    )
  }

  // 5. Idempotency gate — only 'ready' packs can be submitted
  if (disputeRow.defense_pack_status !== 'ready') {
    return Response.json(
      {
        error: 'conflict',
        message: `Defense pack status is '${disputeRow.defense_pack_status}'. Only 'ready' packs can be submitted.`,
        current_status: disputeRow.defense_pack_status,
      },
      { status: 409 },
    )
  }

  // 6. Fetch the defense pack row (untyped cast — table not in generated types)
  const packQuery = supabase.from('dispute_defense_packs') as unknown as {
    select: (cols: string) => {
      eq: (col: string, val: string) => {
        maybeSingle: () => Promise<{
          data: DisputeDefensePackRow | null
          error: { message: string } | null
        }>
      }
    }
  }

  const { data: pack, error: packErr } = await packQuery
    .select(
      'id, dispute_id, signed_consent_url, photo_release_url, session_photos_urls, chat_history_url, deposit_policy_text, receipt_url, bundle_pdf_url, generated_at',
    )
    .eq('dispute_id', disputeId)
    .maybeSingle()

  if (packErr) {
    logger.error({ disputeId, err: packErr }, 'disputes/submit: defense pack lookup error')
    return Response.json({ error: 'internal_error', message: 'Failed to load defense pack.' }, { status: 500 })
  }

  if (!pack) {
    return Response.json(
      { error: 'not_found', message: 'Defense pack not found. The evidence may still be assembling.' },
      { status: 404 },
    )
  }

  // 7. Build Stripe evidence — same mapping as dispute-evidence-submitter.ts cron
  //
  //    Evidence field mapping (DB column → Stripe evidence key):
  //      signed_consent_url   → customer_signature
  //      photo_release_url    → service_documentation
  //      deposit_policy_text  → refund_policy  (truncated to STRIPE_TEXT_MAX)
  //      chat_history_url     → uncategorized_text (reference line + receipt provenance)
  //      session_photos_urls  → uncategorized_text (URL list appended)
  //      bundle_pdf_url       → uncategorized_text (URL appended if set)
  //
  //    Stripe receipt field: receipt_url → uncategorized_text provenance line
  //    (Full file upload via stripe.files.create() is deferred to S46.)

  const receiptLine = [
    `Dispute ID: ${disputeId}`,
    `Charge ID: ${disputeRow.charge_id}`,
    `Studio ID: ${disputeRow.studio_id}`,
  ].join('\n')

  const chatRef = pack.chat_history_url ? `Chat history URL: ${pack.chat_history_url}` : null
  const receiptRef = pack.receipt_url ? `Receipt URL: ${pack.receipt_url}` : null
  const photoRefs =
    pack.session_photos_urls.length > 0
      ? `Session photo URLs:\n${pack.session_photos_urls.join('\n')}`
      : null
  const bundleRef = pack.bundle_pdf_url ? `Bundle PDF: ${pack.bundle_pdf_url}` : null

  const uncategorizedParts = [receiptLine, chatRef, receiptRef, photoRefs, bundleRef].filter(
    (p): p is string => p !== null && p.length > 0,
  )
  const uncategorizedText = uncategorizedParts.join('\n\n').substring(0, STRIPE_TEXT_MAX)

  // 8. Call Stripe
  const stripe = getStripe()
  const now = new Date().toISOString()

  try {
    await stripe.disputes.update(disputeId, {
      evidence: {
        customer_signature: pack.signed_consent_url ?? undefined,
        service_documentation: pack.photo_release_url ?? undefined,
        refund_policy:
          pack.deposit_policy_text.length > 0
            ? pack.deposit_policy_text.substring(0, STRIPE_TEXT_MAX)
            : undefined,
        uncategorized_text: uncategorizedText.length > 0 ? uncategorizedText : undefined,
      },
      submit: true,
    })
  } catch (err: unknown) {
    // Evidence already submitted — treat as success (idempotent)
    if (isStripeError(err)) {
      const code = err.code ?? ''
      const message = err.message ?? ''

      if (code === 'evidence_already_submitted' || message.includes('already been submitted')) {
        logger.warn({ disputeId, userId: user.id }, 'disputes/submit: evidence already submitted — treating as success')
        // Fall through to status update below
      } else if (code === 'evidence_window_closed' || message.includes('evidence window')) {
        logger.error({ disputeId, stripeCode: code }, 'disputes/submit: evidence window closed')
        return Response.json(
          { error: 'evidence_window_closed', message: 'The evidence submission window has closed for this dispute.' },
          { status: 422 },
        )
      } else {
        logger.error({ disputeId, stripeCode: code, stripeType: err.type, err }, 'disputes/submit: Stripe error')
        return Response.json(
          { error: 'stripe_error', message: 'Evidence could not be submitted to Stripe. Please try again.' },
          { status: 502 },
        )
      }
    } else {
      logger.error({ disputeId, err }, 'disputes/submit: unexpected error during Stripe call')
      return Response.json(
        { error: 'internal_error', message: 'An unexpected error occurred.' },
        { status: 500 },
      )
    }
  }

  // 9. Update defense_pack_status to 'submitted' via service-role RPC
  const serviceSupabase = createServiceRoleClient()
  const rpc = serviceSupabase.rpc as unknown as RpcFn
  const { error: rpcErr } = await rpc(RPC.STRIPE_DISPUTE_SET_DEFENSE_PACK_STATUS, {
    p_dispute_id: disputeId,
    p_status: 'submitted' as DisputeDefensePackStatus,
    p_bundle_url: pack.bundle_pdf_url ?? null,
    p_submitted_at: now,
  })

  if (rpcErr) {
    // Non-fatal — evidence was submitted to Stripe. Log the RPC failure and continue.
    logger.error({ disputeId, err: rpcErr }, 'disputes/submit: RPC status update failed (evidence already sent to Stripe)')
  }

  // 10. Audit log
  await logAuditAction(
    user.id,
    'dispute_manual_submit',
    { type: 'stripe_dispute', id: disputeId },
    { dispute_id: disputeId, studio_id: member.studio_id, submitted_at: now },
    member.studio_id,
  )

  return Response.json({ submitted: true, dispute_id: disputeId })
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { cn } from '@/lib/utils'
import type {
  StripeDisputeRow,
  DisputeDefensePackRow,
  StripeDisputeStatus,
  DisputeDefensePackStatus,
} from '@/lib/payments/contracts'
import { DisputeEvidenceDrawer } from '@/components/payments/DisputeEvidenceDrawer'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'

// ─── Types ─────────────────────────────────────────────────────────────────────

type DisputeWithPack = StripeDisputeRow & {
  dispute_defense_packs: Pick<
    DisputeDefensePackRow,
    | 'id'
    | 'signed_consent_url'
    | 'photo_release_url'
    | 'session_photos_urls'
    | 'chat_history_url'
    | 'deposit_policy_text'
    | 'receipt_url'
    | 'bundle_pdf_url'
    | 'generated_at'
  > | null
}

// ─── Dispute status pill ────────────────────────────────────────────────────────

const DISPUTE_STATUS_LABELS: Partial<Record<StripeDisputeStatus, string>> = {
  needs_response: 'Needs response',
  warning_needs_response: 'Needs response',
  under_review: 'Under review',
  warning_under_review: 'Under review',
  warning_closed: 'Closed',
  won: 'Won',
  lost: 'Lost',
  charge_refunded: 'Refunded',
}

function DisputeStatusPill({ status }: { status: StripeDisputeStatus }) {
  const label = DISPUTE_STATUS_LABELS[status] ?? status.replace(/_/g, ' ')
  const isUrgent = status === 'needs_response' || status === 'warning_needs_response'
  const isWon = status === 'won'
  const isLost = status === 'lost'

  return (
    <span
      className={cn(
        'inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-semibold capitalize',
        isUrgent && 'bg-destructive/10 text-destructive',
        isWon && 'bg-[var(--color-onyx)] text-[var(--color-bone)]',
        isLost && 'bg-muted text-muted-foreground',
        !isUrgent && !isWon && !isLost && 'bg-muted text-muted-foreground',
      )}
    >
      {isUrgent && (
        <span className="h-1.5 w-1.5 rounded-full bg-destructive shrink-0" />
      )}
      {label}
    </span>
  )
}

// ─── Defense pack status badge ─────────────────────────────────────────────────

const PACK_STATUS_CONFIG: Record<
  DisputeDefensePackStatus,
  { label: string; className: string }
> = {
  pending: {
    label: 'Assembling evidence...',
    className: 'bg-muted text-muted-foreground',
  },
  assembling: {
    label: 'Assembling...',
    className: 'bg-muted text-muted-foreground',
  },
  ready: {
    label: 'Ready to submit',
    className: 'bg-[var(--color-onyx)] text-[var(--color-bone)]',
  },
  submitted: {
    label: 'Submitted',
    className: 'bg-[var(--color-bone)] text-muted-foreground border border-[var(--color-border)]',
  },
  failed: {
    label: 'Assembly failed',
    className: 'bg-destructive/10 text-destructive',
  },
}

function PackStatusBadge({ status }: { status: DisputeDefensePackStatus }) {
  const config = PACK_STATUS_CONFIG[status] ?? PACK_STATUS_CONFIG.pending
  return (
    <span
      className={cn(
        'inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-semibold',
        config.className,
      )}
    >
      {config.label}
    </span>
  )
}

// ─── Format helpers ────────────────────────────────────────────────────────────

function formatCents(cents: number, currency: string): string {
  return new Intl.NumberFormat('en-US', {
    style: 'currency',
    currency: currency.toUpperCase(),
    minimumFractionDigits: 2,
  }).format(cents / 100)
}

function formatDate(iso: string): string {
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
  }).format(new Date(iso))
}

function formatDateTime(iso: string): string {
  return new Intl.DateTimeFormat('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  }).format(new Date(iso))
}

// ─── Urgency threshold for alert banner (72 hours) ───────────────────────────

function isWithin72Hours(evidenceDueBy: string): boolean {
  const dueMs = new Date(evidenceDueBy).getTime()
  const nowMs = Date.now()
  return dueMs - nowMs <= 72 * 60 * 60 * 1000 && dueMs > nowMs
}

// ─── Dispute card ──────────────────────────────────────────────────────────────

interface DisputeCardProps {
  dispute: DisputeWithPack
  onSubmit: (disputeId: string) => Promise<void>
  onViewEvidence: (dispute: DisputeWithPack) => void
  submitting: string | null // dispute_id currently submitting
}

function DisputeCard({ dispute, onSubmit, onViewEvidence, submitting }: DisputeCardProps) {
  const isSubmitting = submitting === dispute.dispute_id
  const packStatus = dispute.defense_pack_status
  const canSubmit = packStatus === 'ready'
  const canViewEvidence = packStatus === 'submitted' && dispute.dispute_defense_packs !== null
  const isAssembling = packStatus === 'pending' || packStatus === 'assembling'
  const isFailed = packStatus === 'failed'

  return (
    <div className="shadow-soft bg-[var(--color-bone)] border border-[var(--color-border)] rounded-xl p-5">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-start sm:justify-between">
        {/* Left: core dispute info */}
        <div className="flex flex-col gap-2 min-w-0">
          <div className="flex flex-wrap items-center gap-2">
            <DisputeStatusPill status={dispute.status} />
            <PackStatusBadge status={packStatus} />
          </div>

          <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
            <p className="text-[13px] font-mono text-muted-foreground truncate">
              {dispute.dispute_id}
            </p>
            <p
              className="text-[22px] font-[800] leading-none text-[var(--color-onyx)]"
              style={{ fontVariantNumeric: 'tabular-nums' }}
            >
              {formatCents(dispute.amount_cents, dispute.currency)}
            </p>
          </div>

          <p className="text-[12px] text-muted-foreground">
            {dispute.reason.replace(/_/g, ' ')}
            {' · '}
            Opened {formatDate(dispute.created_at)}
          </p>
        </div>

        {/* Right: due date + actions */}
        <div className="flex flex-col items-start sm:items-end gap-3 shrink-0">
          <div className="text-right">
            <p className="text-[11px] font-[700] uppercase tracking-[0.08em] text-muted-foreground">
              Evidence due
            </p>
            <p
              className={cn(
                'text-[13px] font-[600] text-[var(--color-onyx)]',
                isWithin72Hours(dispute.evidence_due_by) && 'text-destructive',
              )}
            >
              {formatDateTime(dispute.evidence_due_by)}
            </p>
          </div>

          <div className="flex items-center gap-2">
            {canSubmit && (
              <Button
                size="sm"
                className="bg-[var(--color-onyx)] text-[var(--color-bone)] hover:bg-[var(--color-onyx)]/90 text-[13px] h-8 px-3"
                onClick={() => onSubmit(dispute.dispute_id)}
                disabled={isSubmitting}
              >
                {isSubmitting ? 'Submitting...' : 'Submit now'}
              </Button>
            )}

            {canViewEvidence && (
              <button
                type="button"
                className="text-[13px] text-muted-foreground hover:text-[var(--color-onyx)] underline underline-offset-2 transition-colors"
                onClick={() => onViewEvidence(dispute)}
              >
                View evidence
              </button>
            )}

            {isAssembling && (
              <Button
                size="sm"
                disabled
                className="bg-muted text-muted-foreground cursor-not-allowed text-[13px] h-8 px-3"
              >
                Assembling...
              </Button>
            )}

            {isFailed && (
              <Button
                size="sm"
                variant="outline"
                className="border-destructive text-destructive hover:bg-destructive/10 text-[13px] h-8 px-3"
