export function DisputesTab() {
  const [disputes, setDisputes] = useState<DisputeWithPack[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [submitting, setSubmitting] = useState<string | null>(null)
  const [evidenceDrawerDispute, setEvidenceDrawerDispute] = useState<DisputeWithPack | null>(null)

  // Fetch disputes on mount
  const fetchDisputes = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const res = await fetch('/api/payments/disputes')
      if (!res.ok) {
        const body = (await res.json()) as { message?: string }
        setError(body.message ?? 'Failed to load disputes.')
        return
      }
      const body = (await res.json()) as { data: DisputeWithPack[] }
      setDisputes(body.data ?? [])
    } catch {
      setError('Failed to load disputes. Please refresh.')
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchDisputes()
  }, [fetchDisputes])

  // Urgency alert: disputes with needs_response AND within 72h
  const urgentDisputes = disputes.filter(
    (d) =>
      (d.status === 'needs_response' || d.status === 'warning_needs_response') &&
      isWithin72Hours(d.evidence_due_by),
  )

  // Submit handler
  const handleSubmit = useCallback(async (disputeId: string) => {
    setSubmitting(disputeId)
    try {
      const res = await fetch(`/api/payments/disputes/${disputeId}/submit`, {
        method: 'POST',
      })
      if (!res.ok) {
        const body = (await res.json()) as { message?: string; error?: string }
        // Surface error in the card without a toast — stays quiet per brand voice
        setError(body.message ?? 'Evidence submission failed.')
        return
      }
      // Refresh list to reflect submitted status
      await fetchDisputes()
    } catch {
      setError('Evidence submission failed. Please try again.')
    } finally {
      setSubmitting(null)
    }
  }, [fetchDisputes])

  // ── Loading state ────────────────────────────────────────────────────────────
  if (loading) {
    return (
      <div className="p-6 space-y-3">
        {Array.from({ length: 3 }).map((_, i) => (
          <DisputeCardSkeleton key={i} />
        ))}
      </div>
    )
  }

  // ── Error state ──────────────────────────────────────────────────────────────
  if (error && disputes.length === 0) {
    return (
      <div className="p-6">
        <div className="shadow-soft border border-[var(--color-border)] rounded-xl p-6 text-center">
          <p className="text-[13px] text-muted-foreground">{error}</p>
          <button
            type="button"
            className="mt-3 text-[13px] text-[var(--color-onyx)] underline underline-offset-2"
            onClick={() => void fetchDisputes()}
          >
            Try again
          </button>
        </div>
      </div>
    )
  }

  // ── Empty state ──────────────────────────────────────────────────────────────
  if (disputes.length === 0) {
    return (
      <div className="p-6">
        <div className="shadow-soft border border-[var(--color-border)] rounded-xl p-12 text-center">
          <p className="font-serif italic text-[22px] text-[var(--color-onyx)] mb-2">
            Disputes
          </p>
          <p className="text-[13px] text-muted-foreground max-w-sm mx-auto">
            No disputes on record. When a client disputes a charge, it appears here.
          </p>
        </div>
      </div>
    )
  }

  return (
    <div className="p-6 space-y-4">
      {/* Urgency alert banner — only if critical disputes within 72h */}
      {urgentDisputes.length > 0 && (
        <div className="border border-[var(--color-border)] bg-destructive/5 rounded-xl px-5 py-4">
          <p className="text-[13px] text-muted-foreground">
            <span className="font-[600] text-[var(--color-onyx)]">
              {urgentDisputes.length}{' '}
              {urgentDisputes.length === 1 ? 'dispute requires' : 'disputes require'} evidence
            </span>{' '}
            before{' '}
            {urgentDisputes.length === 1
              ? formatDateTime(urgentDisputes[0].evidence_due_by)
              : formatDateTime(
                  urgentDisputes.reduce((earliest, d) =>
                    d.evidence_due_by < earliest.evidence_due_by ? d : earliest,
                  ).evidence_due_by,
                )}
            .
          </p>
        </div>
      )}

      {/* Non-fatal inline error */}
      {error && (
        <div className="border border-[var(--color-border)] rounded-xl px-5 py-3">
          <p className="text-[13px] text-muted-foreground">{error}</p>
        </div>
      )}

      {/* Dispute cards */}
      <div className="space-y-3">
        {disputes.map((dispute) => (
          <DisputeCard
            key={dispute.id}
            dispute={dispute}
            onSubmit={handleSubmit}
            onViewEvidence={(d) => setEvidenceDrawerDispute(d)}
            submitting={submitting}
          />
        ))}
      </div>

      {/* Evidence drawer */}
      {evidenceDrawerDispute !== null && (
        <DisputeEvidenceDrawer
          dispute={evidenceDrawerDispute}
          pack={evidenceDrawerDispute.dispute_defense_packs}
          open={true}
          onClose={() => setEvidenceDrawerDispute(null)}
        />
      )}
    </div>
  )
}

